import{z as s,x as B,o as A,c as d,q as l,j as i,D as e,d as t,s as n,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"外部有效性","description":"","frontmatter":{"title":"外部有效性","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pe-external-validity.md","filePath":"econ/pe-external-validity.md","lastUpdated":1791063341000}'),p={name:"econ/pe-external-validity.md"};function m(C,E,u,D,T,h){const r=B("Mermaid");return A(),d("div",null,[E[2]||(E[2]=l('<h1 id="外部有效性" tabindex="-1">外部有效性 <a class="header-anchor" href="#外部有效性" aria-label="Permalink to &quot;外部有效性&quot;">​</a></h1><div class="epigraph"><p>内部有效只是入场券：样本、点位、规模与时间四道断点，任何一道都能让「在此处为真」变成搬运事故。</p><footer>—— Allcott, QJE 2015；Deaton and Cartwright 2018；Athey and Imbens 2017</footer></div><p><a href="/econ/pe-decision-target">上一课</a>把评估的目标改成福利与规则，而规则要在目标情境兑现——效应从研究情境搬过去的过程，就是本课。内外部有效的分界在<a href="/econ/experimental-methods">实验经济学方法</a>已经划过；本课把外推的断点拆开：断在哪、为什么断、怎么搬才是对的搬法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>外推的失败有四个来源，彼此独立。<strong>样本构成</strong>：志愿者、被试池、行政数据覆盖面，都让研究人群不是目标人群——效应异质时，这是加权错误，不是噪声。<strong>点位选择</strong>：Allcott 2015 的要点最锋利——实施者与评估者会按已知效应挑点位（项目先在容易成功的点铺开，或在显著结果出来后扩点），于是文献里的平均效应是「点的选择统计量」，不是任何总体参数；内部有效到无懈可击的 RCT 也拦不住这一条。<strong>规模</strong>：pilot 的小规模效应在推广后改变价格、容量与市场结构——培训项目扩大十倍会压低毕业生工资溢价，补贴扩大十倍会抬高被补贴品价格；局部均衡到一般均衡，per-unit 效应本身就变了，实施机构的带宽同样随规模变。<strong>时间</strong>：短期反应不是长期效应的样本——资本调整、技能积累、规范迁移都在年际尺度上展开，两年试验读不出十年的世界。</p><p><span class="marginnote">数字实例：某职业培训 pilot 覆盖 1 万人、毕业工资溢价 10%；全国推广到 100 万人后，毕业生涌进同一批岗位，雇主不必为证书付高价，溢价被均衡压到 4%。4% 不是 pilot 测错了——per-unit 效应本身随规模变，这是把 pilot 数字乘总人口之前必须问的问题。</span></p><p><span class="marginnote">Allcott 用同一节能项目在多个点位的数据把「按已知效应挑点」的方向算了出来：文献平均被系统性高估。挑大效应的点位发表，等于把均值当成了选择统计量——这与发表偏倚是两种不同的筛子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应对按断点分。样本构成：报告效应在协变量上的分布而不只报均值，把目标人群的加权效应当主交付——这正是决策课福利泛函的输入。点位选择：多点位置随机选点或注册点位，单点位研究声明「这是谁的点」；综述时把点位特征当调节变量记录。规模：区分 per-unit 效应与规模弹性，政策规模的效应估计要价更高——市场均衡的通道要么用均衡模型补，要么声明估计只在 pilot 尺度内有效（接口在<a href="/econ/structural-vs-reduced">结构对约化形式</a>：约化 ATE 是「项目 \\(\\times\\) 情境」的合成物，弹性、MTE 曲线这类参数更可搬运，但搬运它们要模型正确）。时间：短窗效应配长期跟随，或显式声明时间边界。</p>',9)),(A(),i(o,null,{default:e(()=>[n(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EST%5B%22%E7%A0%94%E7%A9%B6%E6%83%85%E5%A2%83%E7%9A%84%E6%95%88%E5%BA%94%22%5D%20--%3E%20SAMP%7B%22%E6%A0%B7%E6%9C%AC%E6%9E%84%E6%88%90%E5%90%8C%E7%9B%AE%E6%A0%87%E4%BA%BA%E7%BE%A4%3F%22%7D%0A%20%20SAMP%20--%3E%7C%E5%90%A6%7C%20REW%5B%22%E6%8C%89%E5%8D%8F%E5%8F%98%E9%87%8F%E9%87%8D%E5%8A%A0%E6%9D%83%22%5D%0A%20%20SAMP%20--%3E%7C%E6%98%AF%7C%20SITE%7B%22%E7%82%B9%E4%BD%8D%E6%98%AF%E6%8C%91%E9%80%89%E7%9A%84%3F%22%7D%0A%20%20SITE%20--%3E%7C%E6%98%AF%7C%20SEL%5B%22%E6%95%88%E5%BA%94%E6%98%AF%E9%80%89%E6%8B%A9%E7%BB%9F%E8%AE%A1%E9%87%8F%22%5D%0A%20%20SITE%20--%3E%7C%E5%90%A6%7C%20SCALE%7B%22%E8%A7%84%E6%A8%A1%E4%B8%8E%E5%9D%87%E8%A1%A1%E9%80%9A%E9%81%93%3F%22%7D%0A%20%20SCALE%20--%3E%7C%E5%8F%98%7C%20GE%5B%22%E5%9D%87%E8%A1%A1%E6%A8%A1%E5%9E%8B%E6%88%96%E5%A3%B0%E6%98%8E%E5%B0%BA%E5%BA%A6%E8%BE%B9%E7%95%8C%22%5D%0A%20%20SCALE%20--%3E%7C%E4%B8%8D%E5%8F%98%7C%20TIME%7B%22%E6%97%B6%E9%97%B4%E7%AA%97%E8%A6%86%E7%9B%96%E8%B0%83%E6%95%B4%3F%22%7D%0A%20%20TIME%20--%3E%7C%E5%90%A6%7C%20LONG%5B%22%E5%A3%B0%E6%98%8E%E6%97%B6%E9%97%B4%E8%BE%B9%E7%95%8C%22%5D%0A%20%20TIME%20--%3E%7C%E6%98%AF%7C%20PORT%5B%22%E5%8F%AF%E6%90%AC%E8%BF%90%3A%20%E5%8F%82%E6%95%B0%E4%B8%8E%E5%88%86%E5%B8%83%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[t("外推失败的机制是效应的"),a("strong",null,"复合性"),t("：\\(\\tau\\) 是项目 \\(\\times\\) 样本 \\(\\times\\) 点位 \\(\\times\\) 尺度 \\(\\times\\) 时间的乘积式合成物，任何一项从研究值变到目标值，\\(\\tau\\) 就变。内部有效控制的是「研究那一格」的混淆；外推要求的是其余格子的映射规则——前者是设计问题，后者是建模与证据组合问题，两者不可互相替代。这也是 RCT 与结构模型的分工：随机化把研究格的映射买断，结构把格子间的映射写出来；只有其一，搬运都缺一条腿。")],-1)),E[5]||(E[5]=a("p",null,"不这么做会错在哪：单点位 RCT 的 \\(\\tau\\) 直接进别处的成本收益，决策课的福利计算从源头错起；多点复制只报均值，把分布的宽度藏掉；把「内部有效」当护身符，回避点位与规模问题。",-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"直觉类比：一个估计出来的 \\(\\tau\\) 像一道菜的「好评率」——它是食材 \\(\\times\\) 厨师 \\(\\times\\) 锅具 \\(\\times\\) 火候的合成物。换一家店（点位）、换食材供应（样本）、把菜谱放大一千份（规模），好评率都会变；真正可搬运的是食谱里的配比（参数与机制），不是那张评分单。")],-1)),(A(),i(o,null,{default:e(()=>[n(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20TAU%5B%22%E8%A7%82%E6%B5%8B%E5%88%B0%E7%9A%84%20tau%22%5D%20--%3E%20F1%5B%22%E9%A1%B9%E7%9B%AE%E8%AE%BE%E8%AE%A1%22%5D%0A%20%20TAU%20--%3E%20F2%5B%22%E6%A0%B7%E6%9C%AC%E6%9E%84%E6%88%90%22%5D%0A%20%20TAU%20--%3E%20F3%5B%22%E7%82%B9%E4%BD%8D%E7%89%B9%E5%BE%81%22%5D%0A%20%20TAU%20--%3E%20F4%5B%22%E5%AE%9E%E6%96%BD%E8%A7%84%E6%A8%A1%22%5D%0A%20%20TAU%20--%3E%20F5%5B%22%E6%97%B6%E9%97%B4%E7%AA%97%22%5D%0A%20%20F2%20--%20%22%E6%8D%A2%E6%88%90%E7%9B%AE%E6%A0%87%E4%BA%BA%E7%BE%A4%22%20--%3E%20CH%5B%22tau%20%E9%9A%8F%E4%B9%8B%E6%94%B9%E5%8F%98%22%5D%0A%20%20F4%20--%20%22pilot%20%E6%89%A9%E5%A4%A7%E5%8D%81%E5%80%8D%22%20--%3E%20CH%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=l('<p>上图回答的问题是「内部有效为什么还搬不动」：四道断点的检查流程在上面这张图里，这里画的是机制本身——\\(\\tau\\) 是五个成分的乘积式合成物，研究只钉住了其中一组的取值，其余格子映射到目标情境时任何一个成分变了，\\(\\tau\\) 就跟着变。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给出「外推系数」的通用公式——不存在。Deaton–Cartwright 对 RCT 证据地位的批评提醒的是平衡：随机化解决分配问题，不解决搬运问题，两句话都要说。多情境外推的形式化装置——证据合成、调节效应、发表过滤——是下一课 meta 分析的地盘，本课只把「效应的分布比均值重要」这句铺垫放下。也不用外推怀疑主义否定评估：搬不动的是数字本身，能搬的是机制、参数与设计。</p><p>后课默认：外推是证据组合问题；多研究的正式合成，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四道断点：样本构成、点位选择、规模与均衡、时间窗。</li><li>点位选择使文献均值成为选择统计量，与发表偏倚是两种筛子。</li><li>per-unit 效应随规模变；pilot 数字直接乘总人口是常见事故。</li><li>可搬运的是参数、分布与机制，不是单点 ATE。</li><li>出处：Allcott, <em>QJE</em> 2015；Deaton and Cartwright 2018；Athey and Imbens 2017。</li></ul>',6))])}const f=s(p,[["render",m]]);export{F as __pageData,f as default};
